using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class BulkReassignTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public BulkReassignTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
        Store.Reset();
    }

    [Fact]
    public async Task BulkReassignIsAtomicOnMissingTicket()
    {
        var client = _factory.CreateClient();
        var fromAgentResp = await client.PostAsJsonAsync("/api/agents", new { name = "A", email = "a@example.com" });
        var fromAgent = await fromAgentResp.Content.ReadFromJsonAsync<Agent>();
        var toAgentResp = await client.PostAsJsonAsync("/api/agents", new { name = "B", email = "b@example.com" });
        var toAgent = await toAgentResp.Content.ReadFromJsonAsync<Agent>();

        var ticketResp = await client.PostAsJsonAsync("/api/tickets", new { subject = "A", agentId = fromAgent!.Id });
        var ticket = await ticketResp.Content.ReadFromJsonAsync<Ticket>();

        var resp = await client.PostAsJsonAsync("/api/tickets/bulk-reassign", new
        {
            toAgentId = toAgent!.Id,
            ticketIds = new[] { ticket!.Id, 999999 }
        });
        Assert.Equal(HttpStatusCode.NotFound, resp.StatusCode);

        var check = await client.GetFromJsonAsync<Ticket>($"/api/tickets/{ticket.Id}");
        Assert.Equal(fromAgent.Id, check!.AgentId);
    }

    [Fact]
    public async Task BulkReassignRespectsDestinationCapacity()
    {
        var client = _factory.CreateClient();
        var fromAgentResp = await client.PostAsJsonAsync("/api/agents", new { name = "A", email = "a@example.com" });
        var fromAgent = await fromAgentResp.Content.ReadFromJsonAsync<Agent>();
        var toAgentResp = await client.PostAsJsonAsync("/api/agents", new { name = "B", email = "b@example.com", maxOpenTickets = 1 });
        var toAgent = await toAgentResp.Content.ReadFromJsonAsync<Agent>();

        var t1Resp = await client.PostAsJsonAsync("/api/tickets", new { subject = "A", agentId = fromAgent!.Id });
        var t1 = await t1Resp.Content.ReadFromJsonAsync<Ticket>();
        var t2Resp = await client.PostAsJsonAsync("/api/tickets", new { subject = "B", agentId = fromAgent.Id });
        var t2 = await t2Resp.Content.ReadFromJsonAsync<Ticket>();

        var resp = await client.PostAsJsonAsync("/api/tickets/bulk-reassign", new
        {
            toAgentId = toAgent!.Id,
            ticketIds = new[] { t1!.Id, t2!.Id }
        });
        Assert.Equal(HttpStatusCode.BadRequest, resp.StatusCode);
    }
}

